type ExtractByKey<T, K extends PropertyKey> = T extends Record<K, any> ? T : never
type RequireKey<T, K extends keyof T> = T & {
	[P in K]-?: Exclude<T[P], null | undefined>
}

type WithKey<T, K extends PropertyKey> = T extends unknown ? (K extends keyof T ? RequireKey<T, K> : never) : never

type MediaUploadData = {
	media: WAMediaUpload
	caption?: string
	ptt?: boolean
	ptv?: boolean
	seconds?: number
	gifPlayback?: boolean
	fileName?: string
	jpegThumbnail?: string
	mimetype?: string
	width?: number
	height?: number
	waveform?: Uint8Array | Buffer | number[]
	backgroundArgb?: number
}

const MIMETYPE_MAP: { [T in MediaType]?: string } = {
	image: 'image/jpeg',
	video: 'video/mp4',
	document: 'application/pdf',
	audio: 'audio/ogg; codecs=opus',
	sticker: 'image/webp',
	'product-catalog-image': 'image/jpeg'
}

const MessageTypeProto = {
	image: WAProto.Message.ImageMessage,
	video: WAProto.Message.VideoMessage,
	audio: WAProto.Message.AudioMessage,
	sticker: WAProto.Message.StickerMessage,
	document: WAProto.Message.DocumentMessage
} as const

/**
 * Uses a regex to test whether the string contains a URL, and returns the URL if it does.
 * @param text eg. hello https://google.com
 * @returns the URL, eg. https://google.com
 */
export const extractUrlFromText = (text: string) => text.match(URL_REGEX)?.[0]

export const generateLinkPreviewIfRequired = async (
	text: string,
	getUrlInfo: MessageGenerationOptions['getUrlInfo'],
	logger: MessageGenerationOptions['logger']
) => {
	const url = extractUrlFromText(text)
	if (!!getUrlInfo && url) {
		try {
			const urlInfo = await getUrlInfo(url)
			return urlInfo
		} catch (error: any) {
			// ignore if fails
			logger?.warn({ trace: error.stack }, 'url generation failed')
		}
	}
}

const assertColor = async (color: any) => {
	let assertedColor
	if (typeof color === 'number') {
		assertedColor = color > 0 ? color : 0xffffffff + Number(color) + 1
	} else {
		let hex = color.trim().replace('#', '')
		if (hex.length <= 6) {
			hex = 'FF' + hex.padStart(6, '0')
		}

		assertedColor = parseInt(hex, 16)
		return assertedColor
	}
}

export const prepareWAMessageMedia = async (
	message: AnyMediaMessageContent,
	options: MessageContentGenerationOptions
) => {
	const logger = options.logger

	let mediaType: (typeof MEDIA_KEYS)[number] | undefined
	for (const key of MEDIA_KEYS) {
		if (key in message) {
			mediaType = key
		}
	}

	if (!mediaType) {
		throw new Boom('Invalid media type', { statusCode: 400 })
	}

	const uploadData: MediaUploadData = {
		...message,
		media: (message as any)[mediaType]
	}
	delete (uploadData as any)[mediaType]
	// check if cacheable + generate cache key
	const cacheableKey =
		typeof uploadData.media === 'object' &&
		'url' in uploadData.media &&
		!!uploadData.media.url &&
		!!options.mediaCache &&
		mediaType + ':' + uploadData.media.url.toString()

	if (mediaType === 'document' && !uploadData.fileName) {
		uploadData.fileName = 'file'
	}

	if (!uploadData.mimetype) {
		uploadData.mimetype = MIMETYPE_MAP[mediaType]
	}

	if (cacheableKey) {
		const mediaBuff = await options.mediaCache!.get<Buffer>(cacheableKey)
		if (mediaBuff) {
			logger?.debug({ cacheableKey }, 'got media cache hit')

			const obj = proto.Message.decode(mediaBuff)
			const key = `${mediaType}Message`

			Object.assign(obj[key as keyof proto.Message]!, { ...uploadData, media: undefined })

			return obj
		}
	}

	const isNewsletter = !!options.jid && isJidNewsletter(options.jid)
	if (isNewsletter) {
		logger?.info({ key: cacheableKey }, 'Preparing raw media for newsletter')
		const { filePath, fileSha256, fileLength } = await getRawMediaUploadData(
			uploadData.media,
			options.mediaTypeOverride || mediaType,
			logger
		)

		const fileSha256B64 = fileSha256.toString('base64')
		const { mediaUrl, directPath, thumbnailDirectPath, thumbnailSha256 } = await options.upload(filePath, {
			fileEncSha256B64: fileSha256B64,
			mediaType: mediaType,
			timeoutMs: options.mediaUploadTimeoutMs,
			newsletter: isNewsletter
		})

		await fs.unlink(filePath)

		const obj = WAProto.Message.fromObject({
			// todo: add more support here
			[`${mediaType}Message`]: (MessageTypeProto as any)[mediaType].fromObject({
				url: mediaUrl,
				directPath,
				fileSha256,
				fileLength,
				thumbnailDirectPath,
				thumbnailSha256,
				...uploadData,
				media: undefined
			})
		})

		if (uploadData.ptv) {
			obj.ptvMessage = obj.videoMessage
			delete obj.videoMessage
		}

		if (obj.stickerMessage) {
			obj.stickerMessage.stickerSentTs = Date.now()
		}

		if (cacheableKey) {
			logger?.debug({ cacheableKey }, 'set cache')
			await options.mediaCache!.set(cacheableKey, WAProto.Message.encode(obj).finish())
		}

		return obj
	}

	const requiresDurationComputation = mediaType === 'audio' && typeof uploadData.seconds === 'undefined'
	const requiresThumbnailComputation =
		(mediaType === 'image' || mediaType === 'video') && typeof uploadData['jpegThumbnail'] === 'undefined'
	const requiresWaveformProcessing =
		mediaType === 'audio' && uploadData.ptt === true && typeof uploadData.waveform === 'undefined'
	const requiresAudioBackground = (options.backgroundColor || (uploadData as any)?.backgroundArgb) && mediaType === 'audio' && uploadData.ptt === true
	const requiresOriginalForSomeProcessing =
		requiresDurationComputation || requiresThumbnailComputation || requiresWaveformProcessing
	const { mediaKey, encFilePath, originalFilePath, fileEncSha256, fileSha256, fileLength } = await encryptedStream(
		uploadData.media,
		options.mediaTypeOverride || mediaType,
		{
			logger,
			saveOriginalFileIfRequired: requiresOriginalForSomeProcessing,
			opts: options.options
		}
	)

	const fileEncSha256B64 = fileEncSha256.toString('base64')
	const [{ mediaUrl, directPath }] = await Promise.all([
		(async () => {
			const result = await options.upload(encFilePath, {
				fileEncSha256B64,
				mediaType,
				timeoutMs: options.mediaUploadTimeoutMs
			})
			logger?.debug({ mediaType, cacheableKey }, 'uploaded media')
			return result
		})(),
		(async () => {
			try {
				if (requiresThumbnailComputation) {
					const { thumbnail, originalImageDimensions } = await generateThumbnail(
						originalFilePath!,
						mediaType as 'image' | 'video',
						options
					)
					uploadData.jpegThumbnail = thumbnail
					if (!uploadData.width && originalImageDimensions) {
						uploadData.width = originalImageDimensions.width
						uploadData.height = originalImageDimensions.height
						logger?.debug('set dimensions')
					}

					logger?.debug('generated thumbnail')
				}

				if (requiresDurationComputation) {
					uploadData.seconds = await getAudioDuration(originalFilePath!)
					logger?.debug('computed audio duration')
				}

				if (requiresWaveformProcessing) {
					uploadData.waveform = await getAudioWaveform(originalFilePath!, logger)
					logger?.debug('processed waveform')
				}

				if (uploadData.waveform) {
					uploadData.waveform = formatWaveform(uploadData.waveform)
				} else if (mediaType === 'audio' && uploadData.ptt === true) {
					uploadData.waveform = generateFallbackWaveform(64)
				}

				if (requiresAudioBackground) {
					uploadData.backgroundArgb = await assertColor(options.backgroundColor || (uploadData as any)?.backgroundArgb)
					logger?.debug('computed backgroundColor audio status')
				}
			} catch (error) {
				logger?.warn({ trace: (error as any).stack }, 'failed to obtain extra info')
			}
		})()
	]).finally(async () => {
		try {
			await fs.unlink(encFilePath)
			if (originalFilePath) {
				await fs.unlink(originalFilePath)
			}

			logger?.debug('removed tmp files')
		} catch (error) {
			logger?.warn('failed to remove tmp file')
		}
	})

	const obj = WAProto.Message.fromObject({
		[`${mediaType}Message`]: MessageTypeProto[mediaType as keyof typeof MessageTypeProto].fromObject({
			url: mediaUrl,
			directPath,
			mediaKey,
			fileEncSha256,
			fileSha256,
			fileLength,
			mediaKeyTimestamp: unixTimestampSeconds(),
			...uploadData,
			waveform: uploadData.waveform ? new Uint8Array(uploadData.waveform) : undefined,
			media: undefined
		} as any)
	})

	if (uploadData.ptv) {
		obj.ptvMessage = obj.videoMessage
		delete obj.videoMessage
	}

	if (cacheableKey) {
		logger?.debug({ cacheableKey }, 'set cache')
		await options.mediaCache!.set(cacheableKey, WAProto.Message.encode(obj).finish())
	}

	return obj
}

export const prepareDisappearingMessageSettingContent = (ephemeralExpiration?: number) => {
	ephemeralExpiration = ephemeralExpiration || 0
	const content: WAMessageContent = {
		ephemeralMessage: {
			message: {
				protocolMessage: {
					type: WAProto.Message.ProtocolMessage.Type.EPHEMERAL_SETTING,
					ephemeralExpiration
				}
			}
		}
	}
	return WAProto.Message.fromObject(content)
}

/**
 * Generate forwarded message content like WA does
 * @param message the message to forward
 * @param options.forceForward will show the message as forwarded even if it is from you
 */
export const generateForwardMessageContent = (message: WAMessage, forceForward?: boolean) => {
	let content = message.message
	if (!content) {
		throw new Boom('no content in message', { statusCode: 400 })
	}

	// hacky copy
	content = normalizeMessageContent(content)
	content = proto.Message.decode(proto.Message.encode(content!).finish())

	let key = Object.keys(content)[0] as keyof proto.IMessage

	let score = (content?.[key] as { contextInfo: proto.IContextInfo })?.contextInfo?.forwardingScore || 0
	score += message.key.fromMe && !forceForward ? 0 : 1
	if (key === 'conversation') {
		content.extendedTextMessage = { text: content[key] }
		delete content.conversation

		key = 'extendedTextMessage'
	}

	const key_ = content?.[key] as { contextInfo: proto.IContextInfo }
	if (score > 0) {
		key_.contextInfo = { forwardingScore: score, isForwarded: true }
	} else {
		key_.contextInfo = {}
	}

	return content
}

export const hasNonNullishProperty = <K extends PropertyKey>(
	message: AnyMessageContent,
	key: K
): message is ExtractByKey<AnyMessageContent, K> => {
	return (
		typeof message === 'object' &&
		message !== null &&
		key in message &&
		(message as any)[key] !== null &&
		(message as any)[key] !== undefined
	)
}

function hasOptionalProperty<T, K extends PropertyKey>(obj: T, key: K): obj is WithKey<T, K> {
	return typeof obj === 'object' && obj !== null && key in obj && (obj as any)[key] !== null
}

/**
 * Converts various button formats (legacy buttons, template buttons, native flow buttons, url/call/copy buttons)
 * into standard WhatsApp Native Flow buttons (quick_reply, cta_url, cta_copy, cta_call).
 */
export const convertButtonToNative = (btn: any) => {
	if (!btn || typeof btn !== 'object') {
		const text = String(btn || 'Button')
		return {
			name: 'quick_reply',
			buttonParamsJson: JSON.stringify({
				display_text: text,
				id: text
			})
		}
	}

	// 1. Already standard native flow format
	if (btn.name && (btn.buttonParamsJson || btn.paramsJson)) {
		return {
			name: btn.name,
			buttonParamsJson:
				typeof btn.buttonParamsJson === 'string'
					? btn.buttonParamsJson
					: typeof btn.paramsJson === 'string'
					? btn.paramsJson
					: JSON.stringify(btn.buttonParamsJson || btn.paramsJson || {})
		}
	}

	// 2. Type 4 / nativeFlowInfo format (often used in menu / selection buttons)
	if (btn.nativeFlowInfo) {
		return {
			name: btn.nativeFlowInfo.name || 'quick_reply',
			buttonParamsJson:
				typeof btn.nativeFlowInfo.paramsJson === 'string'
					? btn.nativeFlowInfo.paramsJson
					: JSON.stringify(btn.nativeFlowInfo.paramsJson || {})
		}
	}

	// 3. Hydrated template button formats
	if (btn.quickReplyButton) {
		return {
			name: 'quick_reply',
			buttonParamsJson: JSON.stringify({
				display_text: btn.quickReplyButton.displayText || 'Button',
				id: btn.quickReplyButton.id || ''
			})
		}
	}

	if (btn.urlButton) {
		const url = btn.urlButton.url || ''
		return {
			name: 'cta_url',
			buttonParamsJson: JSON.stringify({
				display_text: btn.urlButton.displayText || 'Visit URL',
				url,
				merchant_url: url
			})
		}
	}

	if (btn.callButton) {
		return {
			name: 'cta_call',
			buttonParamsJson: JSON.stringify({
				display_text: btn.callButton.displayText || 'Call',
				phone_number: btn.callButton.phoneNumber || ''
			})
		}
	}

	// 4. URL / Web button
	if (btn.url || btn.cta_url) {
		const url = btn.url || btn.cta_url
		const text = btn.text || btn.displayText || btn.buttonText?.displayText || 'Visit URL'
		return {
			name: 'cta_url',
			buttonParamsJson: JSON.stringify({
				display_text: text,
				url,
				merchant_url: url
			})
		}
	}

	// 5. Copy code button
	if (btn.copy || btn.copy_code || btn.cta_copy) {
		const code = btn.copy || btn.copy_code || btn.cta_copy
		const text = btn.text || btn.displayText || btn.buttonText?.displayText || 'Copy'
		return {
			name: 'cta_copy',
			buttonParamsJson: JSON.stringify({
				display_text: text,
				id: btn.id || btn.buttonId || 'copy',
				copy_code: code
			})
		}
	}

	// 6. Call button
	if (btn.call || btn.phoneNumber || btn.cta_call) {
		const phone = btn.call || btn.phoneNumber || btn.cta_call
		const text = btn.text || btn.displayText || btn.buttonText?.displayText || 'Call'
		return {
			name: 'cta_call',
			buttonParamsJson: JSON.stringify({
				display_text: text,
				phone_number: phone
			})
		}
	}

	// 7. Standard Quick Reply / Response button (legacy Baileys format: buttonId, buttonText)
	const id = btn.buttonId || btn.id || ''
	const displayText =
		btn.buttonText?.displayText || btn.displayText || btn.text || (typeof btn === 'string' ? btn : 'Button')

	return {
		name: 'quick_reply',
		buttonParamsJson: JSON.stringify({
			display_text: displayText,
			id
		})
	}
}

/**
 * Sanitizes and prepares an interactiveMessage (nativeFlow, payment buttons, carousel, etc.)
 * into a clean structure that WhatsApp mobile (Android/iOS) and Web can render cleanly without
 * throwing circular reference errors or falling back to "unsupported version".
 */
export const prepareInteractiveMessage = (
	interactiveContent: any,
	options: { defaultTextFallback?: string; viewOnce?: boolean } = {}
): proto.IMessage => {
	if (!interactiveContent || typeof interactiveContent !== 'object') {
		return interactiveContent
	}

	let unwrappedContext: any = undefined
	let targetInteractive: any = undefined
	const isAlreadyViewOnce = Boolean(
		interactiveContent.viewOnceMessage ||
		interactiveContent.viewOnceMessageV2
	)

	if (interactiveContent.viewOnceMessage?.message?.interactiveMessage) {
		unwrappedContext = interactiveContent.viewOnceMessage.message.messageContextInfo
		targetInteractive = interactiveContent.viewOnceMessage.message.interactiveMessage
	} else if (interactiveContent.viewOnceMessageV2?.message?.interactiveMessage) {
		unwrappedContext = interactiveContent.viewOnceMessageV2.message.messageContextInfo
		targetInteractive = interactiveContent.viewOnceMessageV2.message.interactiveMessage
	} else if (interactiveContent.interactiveMessage) {
		unwrappedContext = interactiveContent.messageContextInfo
		targetInteractive = interactiveContent.interactiveMessage
	} else {
		targetInteractive = interactiveContent
		unwrappedContext = interactiveContent.messageContextInfo
	}

	const clean = { ...targetInteractive }
	const garbageKeys = [
		'key',
		'mtype',
		'chat',
		'id',
		'from',
		'isBaileys',
		'sender',
		'fromMe',
		'text',
		'mentionedJid',
		'fakeObj',
		'vM',
		'isGroup',
		'userReceipt',
		'reactions',
		'pollUpdates',
		'eventResponses',
		'statusMentions',
		'messageAddOns',
		'labels',
		'messageStubParameters',
		'statusMentionSources',
		'supportAiCitations'
	]
	for (const k of garbageKeys) {
		delete clean[k]
	}

	if (clean.header && typeof clean.header.hasMediaAttachment === 'undefined') {
		clean.header = {
			...clean.header,
			hasMediaAttachment: Boolean(
				clean.header.imageMessage ||
				clean.header.videoMessage ||
				clean.header.documentMessage
			)
		}
	}

	if (!clean.body || typeof clean.body.text !== 'string' || clean.body.text.trim() === '') {
		clean.body = {
			text: options.defaultTextFallback || clean.body?.text || ' '
		}
	}

	const contextInfo: any = {
		deviceListMetadata: {},
		deviceListMetadataVersion: 2,
		...(unwrappedContext && typeof unwrappedContext === 'object' ? unwrappedContext : {})
	}

	for (const k of garbageKeys) {
		delete contextInfo[k]
	}

	if (Array.isArray(contextInfo.threadId) && contextInfo.threadId.length === 0) {
		delete contextInfo.threadId
	}

	const shouldWrapViewOnce = options.viewOnce !== false
	if (shouldWrapViewOnce) {
		return {
			viewOnceMessage: {
				message: {
					messageContextInfo: contextInfo,
					interactiveMessage: clean
				}
			}
		}
	}

	return {
		messageContextInfo: contextInfo,
		interactiveMessage: clean
	}
}

export const generateWAMessageContent = async (
	message: AnyMessageContent,
	options: MessageContentGenerationOptions
) => {
	const anyMsg = message as any
	let m: WAMessageContent = {}

	if (hasNonNullishProperty(message, 'raw')) {
		delete anyMsg.raw
		return message as WAMessageContent
	} else if (
		hasNonNullishProperty(message, 'code') ||
		hasNonNullishProperty(message, 'links') ||
		hasNonNullishProperty(message, 'table') ||
		hasNonNullishProperty(message, 'richResponse') ||
		hasNonNullishProperty(message, 'html')
	) {
		m = prepareRichResponseMessage(message) as WAMessageContent
	} else if (hasNonNullishProperty(message, 'text')) {
		const extContent = { text: message.text } as WATextMessage

		let urlInfo = message.linkPreview
		if (typeof urlInfo === 'undefined') {
			urlInfo = await generateLinkPreviewIfRequired(message.text, options.getUrlInfo, options.logger)
		}

		if (urlInfo) {
			extContent.matchedText = urlInfo['matched-text']
			extContent.jpegThumbnail = urlInfo.jpegThumbnail
			extContent.description = urlInfo.description
			extContent.title = urlInfo.title
			extContent.previewType = 0

			const img = urlInfo.highQualityThumbnail
			if (img) {
				extContent.thumbnailDirectPath = img.directPath
				extContent.mediaKey = img.mediaKey
				extContent.mediaKeyTimestamp = img.mediaKeyTimestamp
				extContent.thumbnailWidth = img.width
				extContent.thumbnailHeight = img.height
				extContent.thumbnailSha256 = img.fileSha256
				extContent.thumbnailEncSha256 = img.fileEncSha256
			}
		}

		if (options.backgroundColor) {
			extContent.backgroundArgb = await assertColor(options.backgroundColor)
		} else if ((message as any).backgroundArgb) {
			extContent.backgroundArgb = (message as any).backgroundArgb
		}

		if (options.font) {
			extContent.font = options.font
		} else if ((message as any).font) {
			extContent.font = (message as any).font
		}

		if ((message as any).title) {
			extContent.title = (message as any).title
		}

		if ((message as any).jpegThumbnail) {
			extContent.jpegThumbnail = (message as any).jpegThumbnail
		}

		if ((message as any).inviteLinkParentGroupSubjectV2) {
			extContent.inviteLinkParentGroupSubjectV2 = (message as any).inviteLinkParentGroupSubjectV2
		}

		if ((message as any).inviteLinkParentGroupThumbnailV2) {
			extContent.inviteLinkParentGroupThumbnailV2 = (message as any).inviteLinkParentGroupThumbnailV2
		}

		m.extendedTextMessage = extContent
	} else if (hasNonNullishProperty(message, 'contacts')) {
		const contactLen = message.contacts.contacts.length
		if (!contactLen) {
			throw new Boom('require atleast 1 contact', { statusCode: 400 })
		}

		if (contactLen === 1) {
			m.contactMessage = WAProto.Message.ContactMessage.create(message.contacts.contacts[0])
		} else {
			m.contactsArrayMessage = WAProto.Message.ContactsArrayMessage.create(message.contacts)
		}
	} else if (hasNonNullishProperty(message, 'location')) {
		m.locationMessage = WAProto.Message.LocationMessage.create(message.location)
	} else if (hasNonNullishProperty(message, 'react')) {
		if (!message.react.senderTimestampMs) {
			message.react.senderTimestampMs = Date.now()
		}

		m.reactionMessage = WAProto.Message.ReactionMessage.create(message.react)
	} else if (hasNonNullishProperty(message, 'delete')) {
		m.protocolMessage = {
			key: message.delete,
			type: WAProto.Message.ProtocolMessage.Type.REVOKE
		}
	} else if (hasNonNullishProperty(message, 'forward')) {
		m = generateForwardMessageContent(message.forward, message.force)
	} else if (hasNonNullishProperty(message, 'disappearingMessagesInChat')) {
		const exp =
			typeof message.disappearingMessagesInChat === 'boolean'
				? message.disappearingMessagesInChat
					? WA_DEFAULT_EPHEMERAL
					: 0
				: message.disappearingMessagesInChat
		m = prepareDisappearingMessageSettingContent(exp)
	} else if (hasNonNullishProperty(message, 'groupInvite')) {
		m.groupInviteMessage = {}
		m.groupInviteMessage.inviteCode = message.groupInvite.inviteCode
		m.groupInviteMessage.inviteExpiration = message.groupInvite.inviteExpiration
		m.groupInviteMessage.caption = message.groupInvite.text

		m.groupInviteMessage.groupJid = message.groupInvite.jid
		m.groupInviteMessage.groupName = message.groupInvite.subject
		//TODO: use built-in interface and get disappearing mode info etc.
		//TODO: cache / use store!?
		if (options.getProfilePicUrl) {
			const pfpUrl = await options.getProfilePicUrl(message.groupInvite.jid, 'preview')
			if (pfpUrl) {
				const resp = await fetch(pfpUrl, { method: 'GET', dispatcher: options?.options?.dispatcher })
				if (resp.ok) {
					const buf = Buffer.from(await resp.arrayBuffer())
					m.groupInviteMessage.jpegThumbnail = buf
				}
			}
		}
	} else if (hasNonNullishProperty(message, 'pin')) {
		m.pinInChatMessage = {}
		m.messageContextInfo = {}

		m.pinInChatMessage.key = message.pin
		m.pinInChatMessage.type = message.type
		m.pinInChatMessage.senderTimestampMs = Date.now()

		m.messageContextInfo.messageAddOnDurationInSecs = message.type === 1 ? message.time || 86400 : 0
	} else if (hasNonNullishProperty(message, 'buttonReply')) {
		switch (message.type) {
			case 'template':
				m.templateButtonReplyMessage = {
					selectedDisplayText: message.buttonReply.displayText,
					selectedId: message.buttonReply.id,
					selectedIndex: message.buttonReply.index
				}
				break
			case 'plain':
				m.buttonsResponseMessage = {
					selectedButtonId: message.buttonReply.id,
					selectedDisplayText: message.buttonReply.displayText,
					type: proto.Message.ButtonsResponseMessage.Type.DISPLAY_TEXT
				}
				break
		}
	} else if (hasOptionalProperty(message, 'ptv') && message.ptv) {
		const { videoMessage } = await prepareWAMessageMedia({ video: message.video }, options)
		m.ptvMessage = videoMessage
	} else if (hasNonNullishProperty(message, 'product')) {
		const { imageMessage } = await prepareWAMessageMedia({ image: message.product.productImage }, options)
		m.productMessage = WAProto.Message.ProductMessage.create({
			...message,
			product: {
				...message.product,
				productImage: imageMessage
			}
		})
	} else if (hasNonNullishProperty(message, 'listReply')) {
		m.listResponseMessage = { ...message.listReply }
	} else if (hasNonNullishProperty(message, 'event')) {
		m.eventMessage = {}
		const startTime = Math.floor(message.event.startDate.getTime() / 1000)

		if (message.event.call && options.getCallLink) {
			const token = await options.getCallLink(message.event.call, { startTime })
			m.eventMessage.joinLink = (message.event.call === 'audio' ? CALL_AUDIO_PREFIX : CALL_VIDEO_PREFIX) + token
		}

		m.messageContextInfo = {
			// encKey
			messageSecret: message.event.messageSecret || randomBytes(32)
		}

		m.eventMessage.name = message.event.name
		m.eventMessage.description = message.event.description
		m.eventMessage.startTime = startTime
		m.eventMessage.endTime = message.event.endDate ? message.event.endDate.getTime() / 1000 : undefined
		m.eventMessage.isCanceled = message.event.isCancelled ?? false
		m.eventMessage.extraGuestsAllowed = message.event.extraGuestsAllowed
		m.eventMessage.isScheduleCall = message.event.isScheduleCall ?? false
		m.eventMessage.location = message.event.location
	} else if (hasNonNullishProperty(message, 'poll')) {
		message.poll.selectableCount ||= 0
		message.poll.toAnnouncementGroup ||= false

		if (!Array.isArray(message.poll.values)) {
			throw new Boom('Invalid poll values', { statusCode: 400 })
		}

		if (message.poll.selectableCount < 0 || message.poll.selectableCount > message.poll.values.length) {
			throw new Boom(`poll.selectableCount in poll should be >= 0 and <= ${message.poll.values.length}`, {
				statusCode: 400
			})
		}

		m.messageContextInfo = {
			// encKey
			messageSecret: message.poll.messageSecret || randomBytes(32)
		}

		const pollCreationMessage = {
			name: message.poll.name,
			selectableOptionsCount: message.poll.selectableCount,
			options: message.poll.values.map(optionName => ({ optionName }))
		}

		if (message.poll.toAnnouncementGroup) {
			// poll v2 is for community announcement groups (single select and multiple)
			m.pollCreationMessageV2 = pollCreationMessage
		} else {
			if (message.poll.selectableCount === 1) {
				//poll v3 is for single select polls
				m.pollCreationMessageV3 = pollCreationMessage
			} else {
				// poll for multiple choice polls
				m.pollCreationMessage = pollCreationMessage
			}
		}
	} else if (hasNonNullishProperty(message, 'album')) {
		m.albumMessage = {
			expectedImageCount: message.album.expectedImageCount,
			expectedVideoCount: message.album.expectedVideoCount
		}
	} else if (hasNonNullishProperty(message, 'sharePhoneNumber')) {
		m.protocolMessage = {
			type: proto.Message.ProtocolMessage.Type.SHARE_PHONE_NUMBER
		}
	} else if (hasNonNullishProperty(message, 'requestPhoneNumber')) {
		m.requestPhoneNumberMessage = {}
	} else if (hasNonNullishProperty(message, 'limitSharing')) {
		m.protocolMessage = {
			type: proto.Message.ProtocolMessage.Type.LIMIT_SHARING,
			limitSharing: {
				sharingLimited: message.limitSharing === true,
				trigger: 1,
				limitSharingSettingTimestamp: Date.now(),
				initiatedByMe: true
			}
		}
	} else {
		m = await prepareWAMessageMedia(anyMsg, options)
	}

	if (
		(anyMsg.buttons !== undefined && anyMsg.buttons !== null) ||
		(anyMsg.interactiveButtons !== undefined && anyMsg.interactiveButtons !== null)
	) {
		const rawBtns = anyMsg.buttons || anyMsg.interactiveButtons
		const nativeButtons = (Array.isArray(rawBtns) ? rawBtns : []).map(convertButtonToNative)

		const hasMedia = Boolean(
			m && (m.imageMessage || m.videoMessage || m.documentMessage || m.audioMessage || m.locationMessage)
		)

		const interactiveMessage: proto.Message.IInteractiveMessage = {
			body: {
				text: anyMsg.text || anyMsg.caption || ' '
			},
			footer: anyMsg.footer ? { text: anyMsg.footer } : undefined,
			nativeFlowMessage: proto.Message.InteractiveMessage.NativeFlowMessage.create({
				buttons: nativeButtons
			})
		}

		if (hasMedia || anyMsg.title) {
			interactiveMessage.header = {
				title: anyMsg.title || undefined,
				subtitle: anyMsg.subtitle || undefined,
				hasMediaAttachment: hasMedia,
				...(hasMedia ? m : {})
			}
		}

		if (anyMsg.contextInfo) {
			interactiveMessage.contextInfo = anyMsg.contextInfo
		}
		if (anyMsg.mentions) {
			interactiveMessage.contextInfo = {
				...(interactiveMessage.contextInfo || {}),
				mentionedJid: anyMsg.mentions
			}
		}

		const shouldWrapViewOnce = (anyMsg as any).viewOnce !== false
		m = prepareInteractiveMessage(interactiveMessage, {
			viewOnce: shouldWrapViewOnce
		})
	} else if ((anyMsg as any).interactive !== undefined && (anyMsg as any).interactive !== null) {
		m = prepareInteractiveMessage((anyMsg as any).interactive, {
			viewOnce: (message as any).viewOnce !== false
		})
	} else if ((anyMsg as any).interactiveMessage !== undefined && (anyMsg as any).interactiveMessage !== null) {
		m = prepareInteractiveMessage((anyMsg as any).interactiveMessage, {
			viewOnce: (message as any).viewOnce !== false
		})
	} else if (anyMsg.templateButtons !== undefined && anyMsg.templateButtons !== null) {
		const msg: any = {
			hydratedButtons: anyMsg.templateButtons
		}
		if (anyMsg.text !== undefined && anyMsg.text !== null) {
			msg.hydratedContentText = anyMsg.text
		} else {
			if (anyMsg.caption !== undefined && anyMsg.caption !== null && anyMsg.caption) {
				msg.hydratedContentText = anyMsg.caption
			}
			Object.assign(msg, m)
		}
		if (anyMsg.footer !== undefined && anyMsg.footer !== null && anyMsg.footer) {
			msg.hydratedFooterText = anyMsg.footer
		}
		m = {
			templateMessage: {
				fourRowTemplate: msg,
				hydratedTemplate: msg
			}
		}
	}

	if (anyMsg.sections !== undefined && anyMsg.sections !== null) {
		const listMessage: proto.Message.IListMessage = {
			sections: anyMsg.sections,
			buttonText: anyMsg.buttonText,
			title: anyMsg.title,
			footerText: anyMsg.footer,
			description: anyMsg.text,
			listType: proto.Message.ListMessage.ListType.SINGLE_SELECT
		}
		m = { listMessage }
	}

	if (anyMsg.shop !== undefined && anyMsg.shop !== null) {
		const interactiveMessage: proto.Message.IInteractiveMessage = {
			shopStorefrontMessage: proto.Message.InteractiveMessage.ShopMessage.create({
				surface: anyMsg.shop,
				id: anyMsg.id
			})
		}
		if (anyMsg.text !== undefined && anyMsg.text !== null) {
			interactiveMessage.body = {
				text: anyMsg.text
			}
		} else if (anyMsg.caption !== undefined && anyMsg.caption !== null && anyMsg.caption) {
			interactiveMessage.body = {
				text: anyMsg.caption
			}
			interactiveMessage.header = {
				title: anyMsg.title,
				subtitle: anyMsg.subtitle,
				hasMediaAttachment: anyMsg.media ?? false,
				...m
			}
		}
		if (anyMsg.footer !== undefined && anyMsg.footer !== null && anyMsg.footer) {
			interactiveMessage.footer = {
				text: anyMsg.footer
			}
		}
		if (anyMsg.title !== undefined && anyMsg.title !== null && anyMsg.title) {
			interactiveMessage.header = {
				title: anyMsg.title,
				subtitle: anyMsg.subtitle,
				hasMediaAttachment: anyMsg.media ?? false,
				...m
			}
		}
		if (anyMsg.contextInfo !== undefined && anyMsg.contextInfo !== null && anyMsg.contextInfo) {
			interactiveMessage.contextInfo = anyMsg.contextInfo
		}
		if (anyMsg.mentions !== undefined && anyMsg.mentions !== null && anyMsg.mentions) {
			interactiveMessage.contextInfo = { ...interactiveMessage.contextInfo, mentionedJid: anyMsg.mentions }
		}
		m = prepareInteractiveMessage(interactiveMessage, {
			viewOnce: (message as any).viewOnce !== false
		})
	}


	if (hasOptionalProperty(message, 'viewOnce') && !!message.viewOnce && !m.viewOnceMessage && !m.viewOnceMessageV2) {
		m = { viewOnceMessage: { message: m } }
	}

	if (
		(hasOptionalProperty(message, 'mentions') && (message as any).mentions?.length) ||
		(hasOptionalProperty(message, 'mentionAll') && (message as any).mentionAll)
	) {
		const messageType = Object.keys(m)[0]! as Extract<keyof proto.IMessage, MessageWithContextInfo>
		const key = m[messageType]
		if (key && 'contextInfo' in key) {
			key.contextInfo = key.contextInfo || {}
			if ((message as any).mentions?.length) {
				key.contextInfo.mentionedJid = (message as any).mentions
			}

			if ((message as any).mentionAll) {
				key.contextInfo.nonJidMentions = 1
			}
		} else if (key!) {
			key.contextInfo = {
				mentionedJid: (message as any).mentions,
				nonJidMentions: (message as any).mentionAll ? 1 : 0
			}
		}
	}

	if (hasOptionalProperty(message, 'edit')) {
		m = {
			protocolMessage: {
				key: message.edit,
				editedMessage: m,
				timestampMs: Date.now(),
				type: WAProto.Message.ProtocolMessage.Type.MESSAGE_EDIT
			}
		}
	}

	if (hasOptionalProperty(message, 'contextInfo') && !!message.contextInfo) {
		if ((m as any)?.botForwardedMessage?.message?.richResponseMessage) {
			const rich = (m as any).botForwardedMessage.message.richResponseMessage
			rich.contextInfo = { ...rich.contextInfo, ...message.contextInfo }
		} else {
			const messageType = Object.keys(m)[0]! as Extract<keyof proto.IMessage, MessageWithContextInfo>
			const key = m[messageType]
			if ('contextInfo' in key! && !!key.contextInfo) {
				key.contextInfo = { ...key.contextInfo, ...message.contextInfo }
			} else if (key!) {
				key.contextInfo = message.contextInfo
			}
		}
	}

	if (hasOptionalProperty(message, 'albumParentKey') && !!message.albumParentKey) {
		m.messageContextInfo = {
			...m.messageContextInfo,
			messageAssociation: {
				associationType: WAProto.MessageAssociation.AssociationType.MEDIA_ALBUM,
				parentMessageKey: message.albumParentKey
			}
		}
	}

	if (shouldIncludeReportingToken(m)) {
		m.messageContextInfo = m.messageContextInfo || {}
		if (!m.messageContextInfo.messageSecret) {
			m.messageContextInfo.messageSecret = randomBytes(32)
		}
	}

	const isPrivChat = isPrivateChat(options.jid)
	const isExplicitAi = typeof (message as any)?.ai !== 'undefined' ? (message as any).ai : options.ai
	const isAiChatEnabled = options.aiChat !== false

	const normMsg = normalizeMessageContent(m)
	const isInteractive = Boolean(
		normMsg?.interactiveMessage ||
		normMsg?.buttonsMessage ||
		normMsg?.listMessage ||
		(m as any)?.viewOnceMessage?.message?.interactiveMessage ||
		(m as any)?.viewOnceMessageV2?.message?.interactiveMessage
	)

	const shouldAddAi =
		!isInteractive &&
		(isExplicitAi !== undefined
			? Boolean(isExplicitAi)
			: (isAiChatEnabled && isPrivChat))

	if (shouldAddAi && isPrivChat) {
		m.messageContextInfo = m.messageContextInfo || {}
		m.messageContextInfo.supportPayload = BIZ_BOT_SUPPORT_PAYLOAD
	}

	if (!isInteractive) {
		injectAiBotInfo(m, {
			jid: options.jid,
			ai: typeof (message as any)?.ai !== 'undefined' ? (message as any).ai : options.ai,
			aiChat: options.aiChat,
			aiBotName: (message as any)?.aiBotName || options.aiBotName,
			aiBotJid: (message as any)?.aiBotJid || options.aiBotJid
		})
	}

	return WAProto.Message.create(m)
}

/** Check if a jid is a 1-on-1 private chat (not a group, newsletter, or broadcast) */
export const isPrivateChat = (jid?: string): boolean => {
	if (!jid) return true
	return !isJidGroup(jid) && !isJidNewsletter(jid) && !isJidStatusBroadcast(jid) && !isJidBroadcast(jid)
}

/**
 * Injects Meta AI bot badge and forwarding info into message contextInfo
 */
export const injectAiBotInfo = (
	m: WAMessageContent,
	options: {
		jid?: string
		ai?: boolean | string
		aiChat?: boolean
		aiBotName?: string
		aiBotJid?: string
	}
) => {
	// Only inject forwardedAiBotMessageInfo if an explicit bot name or jid is provided
	if (!options.aiBotName && !options.aiBotJid && typeof options.ai !== 'string') {
		return
	}

	// Exclude newsletter and status broadcast (not supported in protocol)
	if (options.jid && (isJidNewsletter(options.jid) || isJidStatusBroadcast(options.jid))) {
		return
	}

	const isPrivChat = isPrivateChat(options.jid)
	const isExplicitAi = options.ai
	const isAiChatEnabled = options.aiChat !== false
	const shouldAddAi =
		isExplicitAi !== undefined
			? Boolean(isExplicitAi)
			: (isAiChatEnabled && isPrivChat)

	if (!shouldAddAi) return
	if ((m as any).botForwardedMessage) return

	const inner = normalizeMessageContent(m) || m
	let key = getContentType(inner)
	if (!key || key === 'protocolMessage' || key === 'reactionMessage') return

	if ((key as string) === 'conversation') {
		const text = (inner as any).conversation
		delete (inner as any).conversation
		inner.extendedTextMessage = { text }
		if (m && (m as any).conversation) {
			delete (m as any).conversation
			m.extendedTextMessage = inner.extendedTextMessage
		}
		key = 'extendedTextMessage'
	}

	const botJid = options.aiBotJid || '867051314767696@bot'

	const target = inner[key as keyof typeof inner] as { contextInfo?: proto.IContextInfo }
	if (target && typeof target === 'object') {
		target.contextInfo = target.contextInfo || {}
		if (!target.contextInfo.forwardedAiBotMessageInfo) {
			target.contextInfo.forwardedAiBotMessageInfo = {
				botJid
			}
			if (options.aiBotName || typeof isExplicitAi === 'string') {
				target.contextInfo.forwardedAiBotMessageInfo.botName =
					typeof isExplicitAi === 'string' ? isExplicitAi : options.aiBotName
			}
		}
		if (typeof target.contextInfo.forwardOrigin === 'undefined') {
			target.contextInfo.forwardOrigin = proto.ContextInfo.ForwardOrigin.META_AI
		}
		target.contextInfo.isForwarded = true
		if (typeof target.contextInfo.forwardingScore !== 'number' || target.contextInfo.forwardingScore < 1) {
			target.contextInfo.forwardingScore = 1
		}
	}

	if (m && inner && key && (m as any)[key]) {
		(m as any)[key] = inner[key]
	}
}

export const generateWAMessageFromContent = (
	jid: string,
	message: WAMessageContent,
	options: MessageGenerationOptionsFromContent
) => {
	// set timestamp to now
	// if not specified
	if (!options.timestamp) {
		options.timestamp = new Date()
	}

	const innerMessage = normalizeMessageContent(message)!
	let key = getContentType(innerMessage)! as Exclude<keyof proto.IMessage, 'conversation'>
	const timestamp = unixTimestampSeconds(options.timestamp)
	const { quoted, userJid } = options

	if ((key as string) === 'conversation') {
		const text = (innerMessage as any).conversation
		delete (innerMessage as any).conversation
		innerMessage.extendedTextMessage = { text }
		if (message && (message as any).conversation) {
			delete (message as any).conversation
			message.extendedTextMessage = innerMessage.extendedTextMessage
		}
		key = 'extendedTextMessage'
	}

	if (quoted?.key && !isJidNewsletter(jid)) {
		const participant = quoted.key.fromMe
			? userJid // TODO: Add support for LIDs
			: quoted.participant || quoted.key.participant || quoted.key.remoteJid

		let quotedMsg = normalizeMessageContent(quoted.message)!
		const msgType = getContentType(quotedMsg)!
		// strip any redundant properties
		quotedMsg = proto.Message.create({ [msgType]: quotedMsg[msgType] })

		const quotedContent = quotedMsg[msgType]
		if (typeof quotedContent === 'object' && quotedContent && 'contextInfo' in quotedContent) {
			delete quotedContent.contextInfo
		}

		const contextInfo: proto.IContextInfo =
			('contextInfo' in innerMessage[key]! && (innerMessage[key] as any)?.contextInfo) || {}
		contextInfo.participant = jidNormalizedUser(participant!)
		contextInfo.stanzaId = quoted.key.id
		contextInfo.quotedMessage = quotedMsg

		// if a participant is quoted, then it must be a group
		// hence, remoteJid of group must also be entered
		if (jid !== quoted.key.remoteJid) {
			contextInfo.remoteJid = quoted.key.remoteJid
		}

		if (contextInfo && innerMessage[key]) {
			/* @ts-ignore */
			innerMessage[key].contextInfo = contextInfo
		}
	}

	if (
		// if we want to send a disappearing message
		!!options?.ephemeralExpiration &&
		// and it's not a protocol message -- delete, toggle disappear message
		key !== 'protocolMessage' &&
		// already not converted to disappearing message
		key !== 'ephemeralMessage' &&
		// newsletters don't support ephemeral messages
		!isJidNewsletter(jid)
	) {
		/* @ts-ignore */
		innerMessage[key].contextInfo = {
			...((innerMessage[key] as any).contextInfo || {}),
			expiration: options.ephemeralExpiration || WA_DEFAULT_EPHEMERAL
			//ephemeralSettingTimestamp: options.ephemeralOptions.eph_setting_ts?.toString()
		}
	}

	injectAiBotInfo(innerMessage, {
		jid,
		ai: (options as any)?.ai,
		aiChat: (options as any)?.aiChat,
		aiBotName: (options as any)?.aiBotName,
		aiBotJid: (options as any)?.aiBotJid
	})

	if (message && innerMessage && key && (message as any)[key]) {
		(message as any)[key] = innerMessage[key]
	}

	message = WAProto.Message.create(message)

	const messageJSON = {
		key: {
			remoteJid: jid,
			fromMe: true,
			id: options?.messageId || generateMessageIDV2()
		},
		message: message,
		messageTimestamp: timestamp,
		messageStubParameters: [],
		participant: isJidGroup(jid) || isJidStatusBroadcast(jid) ? userJid : undefined, // TODO: Add support for LIDs
		status: WAMessageStatus.PENDING
	}
	return WAProto.WebMessageInfo.fromObject(messageJSON) as WAMessage
}

export const generateWAMessage = async (jid: string, content: AnyMessageContent, options: MessageGenerationOptions) => {
	// ensure msg ID is with every log
	options.logger = options?.logger?.child({ msgId: options.messageId })
	const ai = typeof (content as any)?.ai !== 'undefined' ? (content as any).ai : options.ai
	const aiBotName = (content as any)?.aiBotName || options.aiBotName
	const aiBotJid = (content as any)?.aiBotJid || options.aiBotJid
	const mergedOptions = { ...options, ai, aiBotName, aiBotJid, jid }
	return generateWAMessageFromContent(jid, await generateWAMessageContent(content, mergedOptions), mergedOptions)
}

/** Get the key to access the true type of content */
export const getContentType = (content: proto.IMessage | undefined) => {
	if (content) {
		const keys = Object.keys(content)
		const key = keys.find(k => (k === 'conversation' || k.includes('Message')) && k !== 'senderKeyDistributionMessage')
		return key as keyof typeof content
	}
}

/**
 * Normalizes ephemeral, view once messages to regular message content
 * Eg. image messages in ephemeral messages, in view once messages etc.
 * @param content
 * @returns
 */
export const normalizeMessageContent = (content: WAMessageContent | null | undefined): WAMessageContent | undefined => {
	if (!content) {
		return undefined
	}

	// set max iterations to prevent an infinite loop
	for (let i = 0; i < 5; i++) {
		const inner = getFutureProofMessage(content)
		if (!inner) {
			break
		}

		content = inner.message
	}

	return content!

	function getFutureProofMessage(message: typeof content) {
		return (
			message?.associatedChildMessage ||
			message?.botForwardedMessage ||
			message?.botInvokeMessage ||
			message?.botTaskMessage ||
			message?.documentWithCaptionMessage ||
			message?.editedMessage ||
			message?.ephemeralMessage ||
			message?.eventCoverImage ||
			message?.groupMentionedMessage ||
			message?.groupStatusMentionMessage ||
			message?.groupStatusMessage ||
			message?.groupStatusMessageV2 ||
			message?.limitSharingMessage ||
			message?.lottieStickerMessage ||
			message?.newsletterAdminProfileMessage ||
			message?.newsletterAdminProfileMessageV2 ||
			message?.newsletterAdminProfileStatusMessage ||
			message?.spoilerMessage ||
			message?.statusAddYours ||
			message?.statusMentionMessage ||
			message?.viewOnceMessage ||
			message?.viewOnceMessageV2 ||
			message?.viewOnceMessageV2Extension
		)
	}
}

/**
 * Extract the true message content from a message
 * Eg. extracts the inner message from a disappearing message/view once message
 */
export const extractMessageContent = (content: WAMessageContent | undefined | null): WAMessageContent | undefined => {
	const extractFromTemplateMessage = (
		msg: proto.Message.TemplateMessage.IHydratedFourRowTemplate | proto.Message.IButtonsMessage
	) => {
		if (msg.imageMessage) {
			return { imageMessage: msg.imageMessage }
		} else if (msg.documentMessage) {
			return { documentMessage: msg.documentMessage }
		} else if (msg.videoMessage) {
			return { videoMessage: msg.videoMessage }
		} else if (msg.locationMessage) {
			return { locationMessage: msg.locationMessage }
		} else {
			return {
				conversation:
					'contentText' in msg ? msg.contentText : 'hydratedContentText' in msg ? msg.hydratedContentText : ''
			}
		}
	}

	content = normalizeMessageContent(content)

	if (content?.buttonsMessage) {
		return extractFromTemplateMessage(content.buttonsMessage)
	}

	if (content?.templateMessage?.hydratedFourRowTemplate) {
		return extractFromTemplateMessage(content?.templateMessage?.hydratedFourRowTemplate)
	}

	if (content?.templateMessage?.hydratedTemplate) {
		return extractFromTemplateMessage(content?.templateMessage?.hydratedTemplate)
	}

	if (content?.templateMessage?.fourRowTemplate) {
		return extractFromTemplateMessage(content?.templateMessage?.fourRowTemplate)
	}

	return content
}

/**
 * Returns the device predicted by message ID
 */
export const getDevice = (id: string) =>
	/^3A.{18}$/.test(id)
		? 'ios'
		: /^3E.{20}$/.test(id)
			? 'web'
			: /^(.{21}|.{32})$/.test(id)
				? 'android'
				: /^(3F|.{18}$)/.test(id)
					? 'desktop'
					: 'unknown'

/** Upserts a receipt in the message */
export const updateMessageWithReceipt = (msg: Pick<WAMessage, 'userReceipt'>, receipt: MessageUserReceipt) => {
	msg.userReceipt = msg.userReceipt || []
	const recp = msg.userReceipt.find(m => m.userJid === receipt.userJid)
	if (recp) {
		Object.assign(recp, receipt)
	} else {
		msg.userReceipt.push(receipt)
	}
}

/** Update the message with a new reaction */
export const updateMessageWithReaction = (msg: Pick<WAMessage, 'reactions'>, reaction: proto.IReaction) => {
	const authorID = getKeyAuthor(reaction.key)

	const reactions = (msg.reactions || []).filter(r => getKeyAuthor(r.key) !== authorID)
	reaction.text = reaction.text || ''
	reactions.push(reaction)
	msg.reactions = reactions
}

/** Update the message with a new poll update */
export const updateMessageWithPollUpdate = (msg: Pick<WAMessage, 'pollUpdates'>, update: proto.IPollUpdate) => {
	const authorID = getKeyAuthor(update.pollUpdateMessageKey)

	const reactions = (msg.pollUpdates || []).filter(r => getKeyAuthor(r.pollUpdateMessageKey) !== authorID)
	if (update.vote?.selectedOptions?.length) {
		reactions.push(update)
	}

	msg.pollUpdates = reactions
}

/** Update the message with a new event response */
export const updateMessageWithEventResponse = (
	msg: Pick<WAMessage, 'eventResponses'>,
	update: proto.IEventResponse
) => {
	const authorID = getKeyAuthor(update.eventResponseMessageKey)

	const responses = (msg.eventResponses || []).filter(r => getKeyAuthor(r.eventResponseMessageKey) !== authorID)
	responses.push(update)

	msg.eventResponses = responses
}

type VoteAggregation = {
	name: string
	voters: string[]
}

/**
 * Aggregates all poll updates in a poll.
 * @param msg the poll creation message
 * @param meId your jid
 * @returns A list of options & their voters
 */
export function getAggregateVotesInPollMessage(
	{ message, pollUpdates }: Pick<WAMessage, 'pollUpdates' | 'message'>,
	meId?: string
) {
	const opts =
		message?.pollCreationMessage?.options ||
		message?.pollCreationMessageV2?.options ||
		message?.pollCreationMessageV3?.options ||
		[]
	const voteHashMap = opts.reduce(
		(acc, opt) => {
			const hash = sha256(Buffer.from(opt.optionName || '')).toString()
			acc[hash] = {
				name: opt.optionName || '',
				voters: []
			}
			return acc
		},
		{} as { [_: string]: VoteAggregation }
	)

	for (const update of pollUpdates || []) {
		const { vote } = update
		if (!vote) {
			continue
		}

		for (const option of vote.selectedOptions || []) {
			const hash = option.toString()
			let data = voteHashMap[hash]
			if (!data) {
				voteHashMap[hash] = {
					name: 'Unknown',
					voters: []
				}
				data = voteHashMap[hash]
			}

			voteHashMap[hash]!.voters.push(getKeyAuthor(update.pollUpdateMessageKey, meId))
		}
	}

	return Object.values(voteHashMap)
}

type ResponseAggregation = {
	response: string
	responders: string[]
}

/**
 * Aggregates all event responses in an event message.
 * @param msg the event creation message
 * @param meId your jid
 * @returns A list of response types & their responders
 */
export function getAggregateResponsesInEventMessage(
	{ eventResponses }: Pick<WAMessage, 'eventResponses'>,
	meId?: string
) {
	const responseTypes = ['GOING', 'NOT_GOING', 'MAYBE']
	const responseMap: { [_: string]: ResponseAggregation } = {}

	for (const type of responseTypes) {
		responseMap[type] = {
			response: type,
			responders: []
		}
	}

	for (const update of eventResponses || []) {
		const responseType = (update as any).eventResponse || 'UNKNOWN'
		if (responseType !== 'UNKNOWN' && responseMap[responseType]) {
			responseMap[responseType].responders.push(getKeyAuthor(update.eventResponseMessageKey, meId))
		}
	}

	return Object.values(responseMap)
}

/** Given a list of message keys, aggregates them by chat & sender. Useful for sending read receipts in bulk */
export const aggregateMessageKeysNotFromMe = (keys: WAMessageKey[]) => {
	const keyMap: { [id: string]: { jid: string; participant: string | undefined; messageIds: string[] } } = {}
	for (const { remoteJid, id, participant, fromMe } of keys) {
		if (!fromMe) {
			const uqKey = `${remoteJid}:${participant || ''}`
			if (!keyMap[uqKey]) {
				keyMap[uqKey] = {
					jid: remoteJid!,
					participant: participant!,
					messageIds: []
				}
			}

			keyMap[uqKey].messageIds.push(id!)
		}
	}

	return Object.values(keyMap)
}

type DownloadMediaMessageContext = {
	reuploadRequest: (msg: WAMessage) => Promise<WAMessage>
	logger: ILogger
}

const REUPLOAD_REQUIRED_STATUS = [410, 404]

/**
 * Downloads the given message. Throws an error if it's not a media message
 */
export const downloadMediaMessage = async <Type extends 'buffer' | 'stream'>(
	message: WAMessage,
	type: Type,
	options: MediaDownloadOptions,
	ctx?: DownloadMediaMessageContext
) => {
	const result = await downloadMsg().catch(async error => {
		if (
			ctx &&
			typeof error?.status === 'number' && // treat errors with status as HTTP failures requiring reupload
			REUPLOAD_REQUIRED_STATUS.includes(error.status as number)
		) {
			ctx.logger.info({ key: message.key }, 'sending reupload media request...')
			// request reupload
			message = await ctx.reuploadRequest(message)
			const result = await downloadMsg()
			return result
		}

		throw error
	})

	return result as Type extends 'buffer' ? Buffer : Transform

	async function downloadMsg() {
		const mContent = extractMessageContent(message.message)
		if (!mContent) {
			throw new Boom('No message present', { statusCode: 400, data: message })
		}

		const contentType = getContentType(mContent)
		let mediaType = contentType?.replace('Message', '') as MediaType
		const media = mContent[contentType!]

		if (!media || typeof media !== 'object' || (!('url' in media) && !('thumbnailDirectPath' in media))) {
			throw new Boom(`"${contentType}" message is not a media message`)
		}

		let download: DownloadableMessage
		if ('thumbnailDirectPath' in media && !('url' in media)) {
			download = {
				directPath: media.thumbnailDirectPath,
				mediaKey: media.mediaKey
			}
			mediaType = 'thumbnail-link'
		} else {
			download = media
		}

		const stream = await downloadContentFromMessage(download, mediaType, options)
		if (type === 'buffer') {
			const bufferArray: Buffer[] = []
			for await (const chunk of stream) {
				bufferArray.push(chunk)
			}

			return Buffer.concat(bufferArray)
		}

		return stream
	}
}

/** Checks whether the given message is a media message; if it is returns the inner content */
export const assertMediaContent = (content: proto.IMessage | null | undefined) => {
	content = extractMessageContent(content)
	const mediaContent =
		content?.documentMessage ||
		content?.imageMessage ||
		content?.videoMessage ||
		content?.audioMessage ||
		content?.stickerMessage
	if (!mediaContent) {
		throw new Boom('given message is not a media message', { statusCode: 400, data: content })
	}

	return mediaContent
}
